#include "dsky_nv_admission_check.h"
#include "dsky_nv_admission_vectors.h"
uint8_t dsky_nv_admission_checkpoint_input(uint8_t n,apollo_overlay_state *s,p66_bias_io *io,enum dsky_nv_mission *mission,enum dsky_nv_entry *entry){if(n>=64u)return 0;dsky_nv_admission_input(s,io,dsky_nv_numbers[n],mission,entry);return 1;}
uint16_t dsky_nv_admission_checkpoint(uint8_t n,apollo_overlay_state *s,apollo_overlay_state *before){p66_bias_io io,old;enum dsky_nv_mission mission;enum dsky_nv_entry entry;enum dsky_nv_route route;uint16_t f,p,end,failures=0;if(!dsky_nv_admission_checkpoint_input(n,s,&io,&mission,&entry))return 1;*before=*s;old=io;if(dsky_nv_admit(s,&io,mission,entry,&route)!=P66_BIAS_OK||(unsigned)route!=dsky_nv_routes[n])++failures;p=dsky_nv_after_offsets[n];end=dsky_nv_after_offsets[n+1u];for(f=0;f<2050u;++f){uint16_t expected=f<2048u?before->words[f]:f==2048u?old.superbank:old.interrupt_enabled;uint16_t actual=f<2048u?s->words[f]:f==2048u?io.superbank:io.interrupt_enabled;if(p<end&&dsky_nv_after_patch[p][0]==f)expected=dsky_nv_after_patch[p++][1];if(actual!=expected)++failures;}if(p!=end)++failures;return failures;}
